import type { CourseSource, GuidedCourse } from '../../courses';

// Edición en español, traducida de ../en/optimism.ts (sep. 2026).
export const SOURCES: CourseSource[] = [
  { id: 'optimism-maier-seligman', title: 'Maier y Seligman · 2016 · La indefensión aprendida a los cincuenta años: aportes de la neurociencia (Psychological Review)', url: 'https://doi.org/10.1037/rev0000033', type: 'research', finding: 'La revisión concluye que la teoría original de 1967 entendió el mecanismo al revés. La pasividad tras una descarga prolongada e incontrolable es una respuesta por defecto no aprendida (mediada por el núcleo dorsal del rafe). Lo que los animales aprenden es el control: la corteza prefrontal medial detecta el control y entonces inhibe esa respuesta por defecto. Los autores especulan que esto tiene implicaciones para el tratamiento de la depresión.', limitation: 'Se basa sobre todo en investigación con animales; cómo se aplica a personas que enfrentan contratiempos cotidianos es una especulación de los autores, no algo que esta revisión haya probado. Se leyó el resumen (vía Europe PMC).' },
  { id: 'optimism-sweeney', title: 'Sweeney, Anderson y Bailey · 1986 · Estilo atribucional en la depresión: una revisión metaanalítica (Journal of Personality and Social Psychology)', url: 'https://doi.org/10.1037/0022-3514.50.5.974', type: 'research', finding: 'En 104 estudios con casi 15,000 participantes, explicar los sucesos negativos con causas internas, estables y globales se asoció de forma fiable con las puntuaciones de depresión. Explicar los sucesos positivos con causas externas, inestables y específicas también se asoció con la depresión, pero más débilmente. Los patrones se mantuvieron en muestras de estudiantes y psiquiátricas y con sucesos reales e hipotéticos.', limitation: 'Es correlacional: muestra una asociación, no que el estilo explicativo cause la depresión. Es una revisión antigua. Se leyó el resumen (vía Europe PMC).' },
  { id: 'optimism-malouff', title: 'Malouff y Schutte · 2017 · ¿Pueden las intervenciones psicológicas aumentar el optimismo? Un metaanálisis (Journal of Positive Psychology)', url: 'https://doi.org/10.1080/17439760.2016.1221122', type: 'research', finding: '29 ensayos controlados aleatorizados con 3,319 participantes: las intervenciones aumentaron el optimismo con un efecto promedio de g = 0.41. Los efectos fueron mayores con el ejercicio del Mejor Yo Posible, la aplicación presencial, los grupos de control activos, la evaluación dentro del primer día tras la intervención y los análisis de quienes completaron el programa (en lugar de por intención de tratar).', limitation: 'Los efectos mayores en las medidas de corto plazo y en los análisis de quienes completaron el programa sugieren que el cambio duradero es menos seguro. Se leyó el resumen (repositorio de la Universidad de Nueva Inglaterra).' },
  { id: 'optimism-rozanski', title: 'Rozanski et al. · 2019 · Asociación del optimismo con los eventos cardiovasculares y la mortalidad por todas las causas (JAMA Network Open)', url: 'https://jamanetwork.com/journals/jamanetworkopen/fullarticle/2752100', type: 'research', finding: 'Metaanálisis de 15 estudios con 229,391 participantes y un seguimiento medio de 13.8 años. Un mayor optimismo se asoció con un menor riesgo de eventos cardiovasculares (riesgo relativo combinado 0.65, IC del 95% 0.51–0.78; 10 estudios) y de muerte por cualquier causa (0.86, 0.80–0.92; 9 estudios).', limitation: 'Todos los estudios incluidos eran observacionales, con alta heterogeneidad y distintas medidas de optimismo y de ajuste. Muestra una asociación, no que el optimismo cause una mejor salud ni que aumentarlo reduzca el riesgo. Se leyeron los resultados clave y las limitaciones.' },
  { id: 'optimism-prp-meta', title: 'Brunwasser, Gillham y Kim · 2009 · Una revisión metaanalítica del efecto del Programa de Resiliencia de Penn sobre los síntomas depresivos (Journal of Consulting and Clinical Psychology)', url: 'https://ppc.sas.upenn.edu/sites/default/files/prpmetaanalyticreview.pdf', type: 'research', finding: '17 evaluaciones controladas con 2,498 jóvenes de 8 a 18 años. En comparación con ninguna intervención, los participantes informaron menos síntomas depresivos después del programa (d = 0.11), a los 6–8 meses (d = 0.21) y a los 12 meses (d = 0.20). En comparación con condiciones de control activas no hubo diferencia significativa, y el efecto sobre los diagnósticos de depresión no fue significativo.', limitation: 'Efectos pequeños en jóvenes que siguen un programa grupal estructurado; no evalúa a adultos que usan por su cuenta las habilidades ABC. Se leyó el PDF alojado por los autores (resumen y secciones de síntesis).' },
  { id: 'optimism-penn-prp', title: 'Centro de Psicología Positiva, Universidad de Pensilvania · Resiliencia en niños (Programa de Resiliencia de Penn)', url: 'https://ppc.sas.upenn.edu/research/resilience-children', type: 'guidance', finding: 'El Programa de Resiliencia de Penn se construye en torno al modelo ABC de Ellis: los estudiantes aprenden a detectar pensamientos inexactos, evaluar su exactitud y cuestionar las creencias negativas considerando otras interpretaciones, junto con asertividad, resolución de problemas y relajación. Se imparte en 12 sesiones de noventa minutos o en 18–24 sesiones de sesenta minutos. La página cita unos 20 estudios controlados y reconoce algunos hallazgos inconsistentes.', limitation: 'Escrito por los desarrolladores del programa. El metaanálisis independiente encontró efectos pequeños y ninguna ventaja sobre otros programas activos.' },
  { id: 'optimism-hofmann', title: 'Hofmann et al. · 2012 · La eficacia de la terapia cognitivo-conductual: una revisión de metaanálisis (Cognitive Therapy and Research)', url: 'https://pmc.ncbi.nlm.nih.gov/articles/PMC3584580/', type: 'research', finding: 'La revisión abarcó 269 metaanálisis de TCC. El respaldo más sólido fue para la TCC en los trastornos de ansiedad, los trastornos somatomorfos, la bulimia, los problemas de control de la ira y el estrés general. De 11 revisiones que comparaban tasas de respuesta, la TCC tuvo tasas de respuesta más altas que las condiciones de comparación en 7 y más bajas en 1.', limitation: 'Trata de la TCC impartida como terapia, no de autoayuda en una aplicación. Los autores señalan que hay pocos estudios de alta calidad para algunas afecciones y que no hay metaanálisis para grupos como las minorías étnicas o las muestras de bajos ingresos. Se leyó un resumen del texto completo.' },
  { id: 'optimism-smernoff', title: 'Smernoff, Mitnik, Kolodner y Lev-ari · 2015 · Los efectos de la meditación “The Work” (Byron Katie) sobre los síntomas psicológicos y la calidad de vida: un estudio clínico piloto (EXPLORE)', url: 'https://www.sciencedirect.com/science/article/abs/pii/S1550830714002067', type: 'research', finding: '197 personas de una muestra no clínica siguieron un curso de nueve días de The Work. Las puntuaciones de depresión, ansiedad, felicidad y calidad de vida mejoraron de forma significativa (todas p < .001) después del curso y a los seis meses. 164 completaron las medidas posteriores al curso y 102 el seguimiento de seis meses.', limitation: 'Es un estudio piloto de un solo grupo, sin grupo de control y con alto abandono; los autores piden ensayos aleatorizados. Se leyó el resumen.' },
  { id: 'optimism-seligman-exercises', title: 'Seligman, Steen, Park y Peterson · 2005 · Avances de la psicología positiva: validación empírica de intervenciones (American Psychologist)', url: 'https://greatergood.berkeley.edu/images/uploads/Seligman-PosPsychProgress.pdf', type: 'research', finding: 'Estudio en línea, aleatorizado y con placebo: 577 adultos asignados al azar, 411 completaron todos los seguimientos. Todos los grupos, incluido el placebo, se sintieron mejor justo después del ejercicio de una semana. Quienes escribieron tres cosas que salieron bien cada día y por qué, durante una semana, fueron más felices y estuvieron menos deprimidos que al inicio a partir del mes, y se mantuvieron así a los tres y seis meses; usar las fortalezas personales de una manera nueva mostró un patrón similar. Quienes siguieron practicando más allá de la semana fueron quienes siguieron beneficiándose.', limitation: 'Voluntarios autoseleccionados, en su mayoría con estudios superiores, blancos y con depresión leve, que querían ser más felices. Réplicas posteriores encontraron efectos menores o menos específicos. Se leyó el texto completo (copia alojada por el Greater Good Science Center).' },
  { id: 'optimism-mongrain', title: 'Mongrain y Anselmo-Matthews · 2012 · ¿Funcionan los ejercicios de psicología positiva? Una réplica de Seligman et al. (2005) (Journal of Clinical Psychology)', url: 'https://doi.org/10.1002/jclp.21839', type: 'research', finding: 'Con el método original, un control mejorado y un “placebo positivo” añadido, tres cosas buenas y usar las fortalezas personales produjeron aumentos duraderos de la felicidad, pero también lo hizo el placebo positivo. Los ejercicios no superaron a la condición de control en los cambios de la depresión.', limitation: 'Solo se leyó el resumen (vía Europe PMC); no se revisaron los detalles de la muestra. Los autores sugieren que el beneficio puede venir de un efecto general de pensar en información positiva y relevante para uno mismo.' },
  { id: 'optimism-bolier', title: 'Bolier et al. · 2013 · Intervenciones de psicología positiva: un metaanálisis de estudios controlados aleatorizados (BMC Public Health)', url: 'https://link.springer.com/article/10.1186/1471-2458-13-119', type: 'research', finding: '39 estudios con 6,139 participantes. Justo después de los programas: bienestar subjetivo d = 0.34, bienestar psicológico d = 0.20, depresión d = 0.23. A los 3–6 meses: 0.22, 0.16 y 0.17, y el efecto sobre la depresión ya no era significativo.', limitation: 'Ninguno de los estudios cumplió todos los criterios de calidad (20 se calificaron como de baja calidad) y hubo indicios de sesgo de publicación. Combina muchos ejercicios distintos, no solo tres cosas buenas. Se leyeron el resumen y los resultados.' },
  { id: 'optimism-wood', title: 'Wood, Perunovic y Lee · 2009 · Autoafirmaciones positivas: poder para unos, peligro para otros (Psychological Science)', url: 'https://journals.sagepub.com/doi/10.1111/j.1467-9280.2009.02370.x', type: 'research', finding: 'Una encuesta mostró que las personas suelen usar las autoafirmaciones positivas y confiar en ellas. En dos experimentos, las personas con baja autoestima que repitieron una afirmación sobre ser una persona digna de cariño acabaron con peor ánimo que los controles, mientras que las de alta autoestima se sintieron solo un poco mejor.', limitation: 'Experimentos breves que miden el estado de ánimo en el momento; solo se leyó el resumen. No demuestra que toda forma de pensamiento positivo sea dañina.' },
  { id: 'optimism-nhs-cbt', title: 'NHS · Terapia cognitivo-conductual (TCC)', url: 'https://www.nhs.uk/mental-health/talking-therapies-medicine-treatments/talking-therapies-and-counselling/cognitive-behavioural-therapy-cbt/overview/', type: 'guidance', finding: 'El NHS describe la TCC como una terapia psicológica en la que un terapeuta te ayuda a cambiar cómo piensas y actúas. Se usa para la depresión, los trastornos de ansiedad, el TEPT y otras afecciones, por lo general a lo largo de 5 a 15 sesiones; si los síntomas no mejoran, pueden hacer falta más sesiones u otros tratamientos. La página enlaza con ayuda urgente en salud mental.', limitation: 'Los detalles de acceso son específicos de Inglaterra. Los ejercicios de autoayuda de este curso no sustituyen la TCC con un terapeuta capacitado; en una emergencia, llama al número de emergencias de tu país.' },
  { id: 'optimism-distortions', title: 'Psychology Tools · Distorsiones cognitivas: estilos de pensamiento poco útiles (versión ampliada)', url: 'https://www.psychologytools.com/resource/cognitive-distortions-unhelpful-thinking-styles-extended', type: 'guidance', finding: 'Describe 20 estilos de pensamiento poco útiles, entre ellos el pensamiento de todo o nada, la catastrofización, descartar lo positivo, el filtro mental, la lectura de la mente, la generalización excesiva, la personalización y los enunciados con “debería”, y remonta la idea al trabajo de Aaron Beck en los años sesenta, popularizado después por David Burns.', limitation: 'Es un recurso para clínicos que resume categorías comunes; las categorías se superponen y no son un diagnóstico.' },
  { id: 'optimism-seligman-book', title: 'Martin E. P. Seligman · Learned Optimism: How to Change Your Mind and Your Life (1990; edición Vintage, 2006)', url: 'https://www.penguinrandomhouse.com/books/163862/learned-optimism-by-martin-e-p-seligman-phd/', type: 'technique', finding: 'Seligman describe el estilo explicativo (cuán permanentes, generalizadas y personales son tus explicaciones de los contratiempos) y enseña a sustituir los hábitos de rendirse por explicaciones más constructivas. Su método ABCDE amplía el modelo ABC de Albert Ellis con la Disputa y la Energización.', limitation: 'Se leyó la página de la editorial; los pasos del ABCDE y de las tres P se cuentan aquí a partir de descripciones secundarias y de las habilidades muy afines de los programas de resiliencia de Penn, no del texto del libro. Los programas basados en estas ideas muestran efectos pequeños; el libro no se ha probado como tratamiento y no reemplaza uno.' },
  { id: 'optimism-ellis', title: 'Albert Ellis · Emotional disturbance and its treatment in a nutshell (Albert Ellis Institute)', url: 'https://albertellis.org/wp-content/uploads/2021/09/Emotional-Disturbance-and-Its-Treatment-in-a-Nutshell-ABCs-.pdf', type: 'technique', finding: 'Ellis explica el modelo ABC que presentó por primera vez en 1956: los sucesos activadores (A) llevan a consecuencias emocionales y conductuales (C) a través de las creencias (B). Las exigencias rígidas (“debo” y “debería”) y las conclusiones catastróficas alimentan el malestar; disputarlas (D) en lo cognitivo, lo emocional y lo conductual lleva a creencias nuevas, más flexibles y basadas en preferencias (E).', limitation: 'Es una descripción de la terapia racional emotiva conductual hecha por su fundador, no una revisión de investigación; para este curso no se revisó la investigación sobre resultados de la TREC.' },
  { id: 'optimism-beck-thought-record', title: 'Judith S. Beck · Hoja de registro de pensamientos, de Cognitive Behavior Therapy: Basics and Beyond, 3.ª edición (Beck Institute, 2020)', url: 'https://beckinstitute.org/wp-content/uploads/2021/08/Thought-Record-Worksheet.pdf', type: 'technique', finding: 'La hoja tiene columnas para la fecha y la hora, la situación, los pensamientos automáticos con una valoración de la creencia (0–100%), las emociones con su intensidad, la distorsión cognitiva, la respuesta adaptativa y el resultado. Sus preguntas guía indagan en la evidencia a favor y en contra del pensamiento, otras explicaciones, los peores, mejores y más realistas desenlaces, lo que le dirías a un amigo y el efecto de mantener o cambiar el pensamiento.', limitation: 'Es una hoja clínica diseñada para usarse en TCC. Usada por sí sola es autoayuda, y el uso autoguiado está menos estudiado que la TCC dirigida por un terapeuta.' },
  { id: 'optimism-the-work', title: 'Byron Katie · Do The Work: instrucciones (thework.com)', url: 'https://thework.com/instruction-the-work-byron-katie/', type: 'technique', finding: 'Las instrucciones de Katie: escribe juicios estresantes sobre una persona o situación en frases cortas y sencillas; luego hazle cuatro preguntas a cada uno (si es verdad, si puedes estar absolutamente seguro, cómo reaccionas cuando lo crees, quién serías sin él); después da la vuelta al pensamiento (hacia ti, hacia la otra persona, hacia lo opuesto) y encuentra al menos tres ejemplos genuinos de cada inversión.', limitation: 'Son las instrucciones del propio autor; la base de investigación se limita a estudios tempranos y sin control.' },
  { id: 'optimism-mrt', title: 'Reivich, Seligman y McBride · 2011 · Entrenamiento en Resiliencia Maestra en el Ejército de EE. UU. (American Psychologist)', url: 'https://ppc.sas.upenn.edu/sites/default/files/mrtinarmyjan2011.pdf', type: 'technique', finding: 'Describe un curso de resiliencia para sargentos del Ejército adaptado del Programa de Resiliencia de Penn: el modelo ABC y el estilo explicativo, las trampas del pensamiento (como generalizar en exceso, sacar conclusiones precipitadas y un estilo “yo”), las creencias más profundas tipo “iceberg”, ponerlo en perspectiva (peor, mejor y más probable desenlace, y luego un plan) y cazar lo bueno, un registro diario de cosas buenas.', limitation: 'Es la descripción de un programa. En el momento de la publicación solo se informó la opinión inmediata de los participantes y las evaluaciones controladas seguían en curso. Se leyó el PDF alojado por los autores.' },
  { id: 'optimism-ggia-three-good-things', title: 'Greater Good in Action (UC Berkeley) · Tres cosas buenas', url: 'https://ggia.berkeley.edu/practice/three-good-things', type: 'technique', finding: 'Instrucciones: dedica unos diez minutos al día, durante al menos una semana, a escribir tres cosas que salieron bien, con detalles, cómo te hicieron sentir y qué las causó. La página cita el estudio de Seligman de 2005 y estudios posteriores en varios países que informan de mejor bienestar y menos pesimismo, depresión o ansiedad.', limitation: 'Es una guía de práctica universitaria que resume estudios favorables y dice que hace falta más investigación entre culturas. Las réplicas sugieren que los efectos son pequeños y no siempre específicos de este ejercicio.' },
];

